  try{const {dx,dy}=motionEdgePan(drag.client,size(),elapsed);if(dx||dy){const view=panMotionView(getView(),dx,dy);if(!pathPoint(drag.client,view,true))return;preview(null,view);sync();}}
  catch(e){stopEdge();drag.edgeLimited=true;status(e.message,true);return;}
