 function beginGesture(){const pts=[...pointers.values()];gesture={view:clone(navigationView),points:pts.map(p=>({...p}))};}
 stage.addEventListener('pointerdown',e=>{if(!opened)return;consume(e);if(framing()&&e.button===0){pointers.set(e.pointerId,local(e));stage.setPointerCapture(e.pointerId);beginGesture();return;}if(!capture||e.button!==0)return;if(e.pointerType==='touch'){status('Use pen or mouse to define a path; numeric endpoints work with touch');return;}try{assertCurrent();if(capture==='camera'){draft.target.x=point(e).x;draft.target.y=point(e).y;capture=null;populate();return;}drag={id:e.pointerId,origin:point(e),before:clone(draft.path),client:local(e),edgeLimited:false};draft.path=[{x:0,y:0}];stage.setPointerCapture(e.pointerId);stopEdge();edgeRaf=requestAnimationFrame(edgeTick);sync();}catch(err){stopEdge();error(err);}});
 stage.addEventListener('pointermove',e=>{if(framing()&&pointers.has(e.pointerId)){consume(e);pointers.set(e.pointerId,local(e));try{const pts=[...pointers.values()],before=gesture.points,centre=a=>({x:a.reduce((n,p)=>n+p.x,0)/a.length,y:a.reduce((n,p)=>n+p.y,0)/a.length}),a=centre(before),b=centre(pts);let v=gesture.view;if(pts.length===2){const distance=a=>Math.hypot(a[1].x-a[0].x,a[1].y-a[0].y),old=distance(before);if(old>1)v=zoomMotionView(v,Math.max(.01,distance(pts)/old),a);}showNavigation(panMotionView(v,b.x-a.x,b.y-a.y));}catch(err){error(err);}return;}if(!drag||drag.id!==e.pointerId)return;consume(e);drag.client=local(e);if(!drag.edgeLimited&&pathPoint(drag.client,getView()))sync();});
