 window.addEventListener('keydown',e=>{if(!opened)return;e.stopImmediatePropagation();if(e.key==='Escape'){consume(e);if(capture)finishCapture(true);else if(session)stop();else close();return;}if(framing()&&e.target===stage){try{if(e.key==='Enter'){consume(e);finishCapture();return;}if(e.key==='+'||e.key==='='||e.key==='-'){consume(e);zoom(e.key==='-'?.8:1.25);return;}const deltas={ArrowLeft:[80,0],ArrowRight:[-80,0],ArrowUp:[0,80],ArrowDown:[0,-80]};if(deltas[e.key]){consume(e);showNavigation(panMotionView(navigationView,...deltas[e.key]));return;}}catch(err){error(err);}}if(session){if(e.code==='Space'){consume(e);running?pause():paused?resume():advance();}else if(['ArrowRight','Enter'].includes(e.key)&&!e.target.closest('button')){consume(e);advance();}else if(!e.target.closest('#motion-transport'))consume(e);}else if(!e.target.closest('#motion-panel,#motion-stage,#motion-capture-bar'))consume(e);
  if(e.key==='Tab'){const region=session?transport:capture?$('motion-capture-bar'):panel,items=[...(capture?[stage]:[]),...region.querySelectorAll('button,input,select,[tabindex]')].filter(el=>!el.disabled&&!el.hidden&&el.getClientRects().length);if(items.length&&(e.shiftKey&&document.activeElement===items[0]||!e.shiftKey&&document.activeElement===items.at(-1))){consume(e);(e.shiftKey?items.at(-1):items[0]).focus();}}
 },true);
 function suspend(){if(capture==='path'&&drag)finishCapture(true);pause();}
